/// Configuration for the Anthropic Messages API client.
///
/// All fields have production-ready defaults. The `api_key` is sourced from the
/// `ANTHROPIC_API_KEY` environment variable by default.
#[derive(Clone)]
pub struct AnthropicConfig {
    /// Anthropic API key. See `Display` and `Debug` for redacted formatting.
    pub api_key: String,
    /// Base URL for the Anthropic API.
    pub base_url: String,
    /// Default model identifier to use for requests.
    pub default_model: String,
    /// Default maximum output tokens for requests.
    pub default_max_tokens: u64,
    /// Timeout for API requests.
    pub request_timeout: Duration,
}

impl Default for AnthropicConfig {
    fn default() -> Self {
        Self {
            api_key: std::env::var("ANTHROPIC_API_KEY")
                .unwrap_or_default(),
            base_url: "https://api.anthropic.com".into(),
            default_model: "claude-sonnet-4-20250513".into(),
            default_max_tokens: 8192,
            request_timeout: Duration::from_secs(120),
        }
    }
}

impl fmt::Display for AnthropicConfig {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let redacted = if self.api_key.len() >= 4 {
            format!("{}***", &self.api_key[..4])
        } else {
            "***".into()
        };

        write!(
            f,
            "AnthropicConfig {{ api_key: {}, base_url: {}, default_model: {}, \
             default_max_tokens: {}, request_timeout: {:?} }}",
            redacted,
            self.base_url,
            self.default_model,
            self.default_max_tokens,
            self.request_timeout,
        )
    }
}

impl fmt::Debug for AnthropicConfig {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        // Reuse the redacted Display output.
        fmt::Display::fmt(self, f)
    }
}

impl AnthropicConfig {
    /// Create a new `AnthropicConfig` with the given API key and all other
    /// fields set to their [`Default`] values.
    pub fn new(api_key: impl Into<String>) -> Self {
        Self {
            api_key: api_key.into(),
            ..Self::default()
        }
    }
}

