//! Anthropic backend composition and integration factory.
//!
//! This module provides:
//!
//! 1. [`AnthropicBackend`] — a zero-sized constructor that composes
//!    [`AnthropicClient`] with [`GenericModelBackend`] so call sites can
//!    write `AnthropicBackend::new(config)` (matching spec §12's example).
//!
//! 2. [`AnthropicFactory`] — an [`IntegrationFactory`] implementation that
//!    deserializes an [`AnthropicConfig`] from JSON, constructs an
//!    [`AnthropicBackend`], and returns it as `Arc<dyn ExecutionBackend>`,
//!    enabling dynamic backend instantiation via the runtime's integration
//!    registry (spec §15/16).
//!
//! [`AnthropicClient`]: crate::client::AnthropicClient
//! [`GenericModelBackend`]: harness_generic_backend::GenericModelBackend

use std::sync::Arc;

use harness_generic_backend::GenericModelBackend;
use harness_protocol::backend::BackendDescriptor;
use harness_runtime::traits::ExecutionBackend;

use crate::client::AnthropicClient;
use crate::config::AnthropicConfig;

// ---------------------------------------------------------------------------
// AnthropicBackend
// ---------------------------------------------------------------------------

/// A zero-sized constructor that composes [`AnthropicClient`] (a
/// [`ModelClient`](harness_model::client::ModelClient) implementation) with
/// [`GenericModelBackend`] (an [`ExecutionBackend`] implementation).
///
/// # Usage
///
/// ```ignore
/// let backend: GenericModelBackend = AnthropicBackend::new(config);
/// let session = harness
///     .session()
///     .backend(Arc::new(backend))
///     // ...
///     .start()
///     .await?;
/// ```
pub struct AnthropicBackend;

impl AnthropicBackend {
    /// Create a new [`GenericModelBackend`] backed by the Anthropic API.
    ///
    /// This is a convenience constructor that:
    /// 1. Creates an [`AnthropicClient`] from the given [`AnthropicConfig`].
    /// 2. Wraps it in `Arc<dyn ModelClient>`.
    /// 3. Passes it to [`GenericModelBackend::new`].
    pub fn new(config: AnthropicConfig) -> GenericModelBackend {
        let client = Arc::new(AnthropicClient::new(config));
        GenericModelBackend::new(client)
    }
}

// ---------------------------------------------------------------------------
// IntegrationFactory
// ---------------------------------------------------------------------------

/// A factory that can create [`ExecutionBackend`] instances from a JSON
/// configuration blob.
///
/// This trait is used by the runtime's [`IntegrationRegistry`] to
/// reconstruct backends dynamically (spec §15/16). Each integration
/// family (Anthropic, OpenAI, Claude Code, …) implements this trait and
/// registers a singleton instance.
///
/// # Object safety
///
/// This trait is `dyn`-compatible — all methods take `&self` and return
/// owned values.
pub trait IntegrationFactory: Send + Sync {
    /// Returns the unique identifier for this integration family
    /// (e.g. `"anthropic"`, `"openai"`, `"claude-code"`).
    fn id(&self) -> &'static str;

    /// Returns a [`BackendDescriptor`] describing the integration's
    /// static capabilities and identity.
    fn descriptor(&self) -> BackendDescriptor;

    /// Create a new [`ExecutionBackend`] from a JSON configuration value.
    ///
    /// The `config_json` is deserialized into the integration-specific
    /// configuration type (e.g. [`AnthropicConfig`]). If deserialization
    /// fails, the error is returned as a boxed error.
    fn create(
        &self,
        config_json: serde_json::Value,
    ) -> Result<Arc<dyn ExecutionBackend>, Box<dyn std::error::Error>>;
}

// ---------------------------------------------------------------------------
// AnthropicFactory
// ---------------------------------------------------------------------------

/// A singleton [`IntegrationFactory`] for the Anthropic integration.
///
/// # Usage
///
/// ```ignore
/// let factory = Arc::new(AnthropicFactory);
/// registry.register(factory);
///
/// // Later, during session restore:
/// let config = serde_json::json!({
///     "api_key": "sk-ant-...",
///     "base_url": "https://api.anthropic.com",
///     "default_model": "claude-sonnet-4-20250513",
/// });
/// let backend = factory.create(config)?;
/// ```
pub struct AnthropicFactory;

impl IntegrationFactory for AnthropicFactory {
    fn id(&self) -> &'static str {
        "anthropic"
    }

    fn descriptor(&self) -> BackendDescriptor {
        BackendDescriptor {
            id: harness_protocol::ids::BackendId::new(),
            name: "Anthropic".to_string(),
            description: "Anthropic Messages API via GenericModelBackend".to_string(),
            capabilities: harness_protocol::backend::BackendCapabilities {
                streaming: true,
                reasoning_stream: true,
                tool_calls: true,
                parallel_tool_calls: true,
                host_managed_tools: true,
                ..Default::default()
            },
        }
    }

    fn create(
        &self,
        config_json: serde_json::Value,
    ) -> Result<Arc<dyn ExecutionBackend>, Box<dyn std::error::Error>> {
        let config: AnthropicConfig = serde_json::from_value(config_json)?;
        let backend = AnthropicBackend::new(config);
        Ok(Arc::new(backend))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    // ------------------------------------------------------------------
    // AnthropicBackend tests
    // ------------------------------------------------------------------

    #[test]
    fn anthropic_backend_new_returns_generic_model_backend() {
        // Constructing with an empty config + env var API key
        // should produce a GenericModelBackend without panicking.
        let config = AnthropicConfig::new("test-key-12345");
        let backend = AnthropicBackend::new(config);

        // The backend should have a descriptor with reasonable defaults.
        let descriptor = backend.descriptor();
        assert!(!descriptor.id.to_string().is_empty());
        assert_eq!(descriptor.name, "generic-model-backend");

        // Capabilities should be derived from AnthropicClient::capabilities().
        let caps = backend.capabilities();
        assert!(caps.streaming, "Anthropic supports streaming");
        assert!(caps.reasoning_stream, "Anthropic supports reasoning stream");
        assert!(caps.tool_calls, "Anthropic supports tool calls");
        assert!(caps.parallel_tool_calls, "Anthropic supports parallel tool calls");
        assert!(caps.host_managed_tools, "Anthropic uses host-managed tools");
    }

    // ------------------------------------------------------------------
    // IntegrationFactory tests
    // ------------------------------------------------------------------

    #[test]
    fn anthropic_factory_id() {
        let factory = AnthropicFactory;
        assert_eq!(factory.id(), "anthropic");
    }

    #[test]
    fn anthropic_factory_descriptor() {
        let factory = AnthropicFactory;
        let descriptor = factory.descriptor();
        assert_eq!(descriptor.name, "Anthropic");
        assert!(!descriptor.id.to_string().is_empty());
        assert!(
            descriptor.capabilities.streaming,
            "descriptor should advertise streaming"
        );
        assert!(
            descriptor.capabilities.tool_calls,
            "descriptor should advertise tool_calls"
        );
    }

    #[test]
    fn anthropic_factory_create_success() {
        let factory = AnthropicFactory;
        let config_json = serde_json::json!({
            "api_key": "sk-ant-test-abcdef",
            "base_url": "https://api.anthropic.com",
            "default_model": "claude-sonnet-4-20250513",
            "default_max_tokens": 8192,
            "request_timeout_secs": 120,
        });

        let result = factory.create(config_json);
        assert!(result.is_ok(), "factory.create should succeed with valid config");

        let backend = result.unwrap();
        let descriptor = backend.descriptor();
        assert!(!descriptor.id.to_string().is_empty());
        assert!(
            descriptor.capabilities.streaming,
            "created backend should advertise streaming"
        );
    }

    #[test]
    fn anthropic_factory_create_with_empty_api_key() {
        let factory = AnthropicFactory;
        let config_json = serde_json::json!({
            "api_key": "",
        });

        let result = factory.create(config_json);
        assert!(
            result.is_ok(),
            "factory.create should succeed even with empty api_key"
        );
    }

    #[test]
    fn anthropic_factory_create_fails_on_invalid_json() {
        let factory = AnthropicFactory;
        // Missing required fields for AnthropicConfig (api_key is not required
        // at the serde level due to Default impl, but an unexpected type should fail).
        let config_json = serde_json::json!({
            "api_key": 12345, // wrong type: number instead of string
        });

        let result = factory.create(config_json);
        assert!(
            result.is_err(),
            "factory.create should fail with invalid config types"
        );
    }

    #[test]
    fn anthropic_factory_create_fails_on_null() {
        let factory = AnthropicFactory;
        let config_json = serde_json::Value::Null;

        let result = factory.create(config_json);
        assert!(
            result.is_err(),
            "factory.create should fail with null config"
        );
    }

    // ------------------------------------------------------------------
    // Trait object dispatch
    // ------------------------------------------------------------------

    #[test]
    fn factory_can_be_used_as_trait_object() {
        let factory: Arc<dyn IntegrationFactory> = Arc::new(AnthropicFactory);
        assert_eq!(factory.id(), "anthropic");

        let config_json = serde_json::json!({
            "api_key": "sk-ant-test-xyz",
        });
        let backend = factory.create(config_json);
        assert!(backend.is_ok(), "trait-object dispatch should work");
    }
}

//! Full session end-to-end test using recorded SSE fixtures (zero network).
//!
//! This test exercises the complete path:
//!
//! SessionBuilder
//!   → SessionRuntime
//!     → AgentRunner
//!       → GenericModelBackend (inline)
//!         → ModelClient (inline fake)
//!           → wire.rs SSE parsing (inline)
//!             → ModelEvent emission
//!           → ExecutionEvent translation
//!         → SessionEvent output
//!
//! Zero-network behaviour is achieved by injecting a [`FakeAnthropicHttpClient`]
//! that returns pre-recorded SSE byte sequences for matching request patterns.
//!
//! The test verifies:
//! - Text deltas are streamed as `AssistantTextDelta` events.
//! - Tool calls have the correct names, arguments, and ordering.
//! - Usage updates carry input/output token counts.
//! - The event stream terminates with `Completed(Success)`.
//! - Deterministic output — identical bytes produce identical events.

// ===========================================================================
// Imports
// ===========================================================================

use std::sync::Arc;

use async_trait::async_trait;
use tokio::sync::broadcast;
use tokio_util::sync::CancellationToken;

use harness_engine::Harness;
use harness_protocol::backend::{
    BackendCapabilities, BackendDescriptor, ExecutionError, ExecutionEvent, ExecutionRequest,
    ExecutionResult,
};
use harness_protocol::events::{AgentEvent, AgentEventEnvelope, AgentOutcome};
use harness_protocol::ids::{RequestId, ToolCallId};
use harness_protocol::tools::{ToolCall, ToolDescriptor};
use harness_protocol::usage::{Cost, ModelUsage, UsageValue};
use harness_runtime::traits::{ExecutionBackend, ToolExecutor, ToolRegistry};

