// ===========================================================================
// Helper: drain buffered events from a broadcast receiver
// ===========================================================================

fn drain_events(rx: &mut broadcast::Receiver<AgentEventEnvelope>) -> Vec<AgentEvent> {
    let mut events = Vec::new();
    while let Ok(envelope) = rx.try_recv() {
        events.push(envelope.event);
    }
    events
}

// ===========================================================================
// Test: text response streaming
// ===========================================================================

/// Sends a plain prompt through the full session stack and verifies that
/// the text deltas from the fixture SSE stream arrive as `AssistantTextDelta`
/// events in the correct order, followed by `Completed(Success)`.
#[tokio::test]
async fn session_streams_text_deltas_from_sse_fixtures() {
    let factory = Arc::new(FakeAnthropicHttpClient::new());
    let model_client = Arc::new(FakeModelClient::new(factory));
    let backend = Arc::new(GenericModelBackend::new(model_client));

    let tool_registry = Arc::new(NoTools);

    let handle = Harness::new()
        .session()
        .backend(backend)
        .tools(tool_registry)
        .start()
        .await
        .expect("SessionBuilder::start() should succeed");

    let mut rx = handle.subscribe();

    handle
        .send("write a simple greeting")
        .await
        .expect("SessionHandle::send() should succeed");

    // Collect events until Completed is observed.
    let mut all_events: Vec<AgentEvent> = Vec::new();
    for _ in 0..50 {
        let batch = drain_events(&mut rx);
        if !batch.is_empty() {
            all_events.extend(batch);
            if all_events
                .iter()
                .any(|e| matches!(e, AgentEvent::Completed { .. }))
            {
                break;
            }
        }
        tokio::time::sleep(std::time::Duration::from_millis(20)).await;
    }

    // Filter out StateChanged to see the core sequence.
    let core: Vec<&AgentEvent> = all_events
        .iter()
        .filter(|e| !matches!(e, AgentEvent::StateChanged { .. }))
        .collect();

    assert!(
        core.len() >= 4,
        "expected at least 4 core events (RunStarted, 2x AssistantTextDelta, Completed); got {}: {:?}",
        core.len(),
        core
    );

    // 0. RunStarted
    assert!(
        matches!(core[0], AgentEvent::RunStarted { .. }),
        "event[0] should be RunStarted, got {:?}",
        core[0]
    );

    // 1. AssistantTextDelta("Hello, ")
    assert!(
        matches!(&core[1], AgentEvent::AssistantTextDelta { delta, .. } if delta == "Hello, "),
        "event[1] should be AssistantTextDelta(\"Hello, \"), got {:?}",
        core[1]
    );

    // 2. AssistantTextDelta("world!")
    assert!(
        matches!(&core[2], AgentEvent::AssistantTextDelta { delta, .. } if delta == "world!"),
        "event[2] should be AssistantTextDelta(\"world!\"), got {:?}",
        core[2]
    );

    // 3. Completed(Success)
    assert!(
        matches!(core[3], AgentEvent::Completed { outcome } if *outcome == AgentOutcome::Success),
        "event[3] should be Completed(Success), got {:?}",
        core[3]
    );

    // Verify ordering.
    let run_started_idx = all_events
        .iter()
        .position(|e| matches!(e, AgentEvent::RunStarted { .. }));
    let delta1_idx = all_events
        .iter()
        .position(|e| matches!(e, AgentEvent::AssistantTextDelta { delta, .. } if delta == "Hello, "));
    let delta2_idx = all_events
        .iter()
        .position(|e| matches!(e, AgentEvent::AssistantTextDelta { delta, .. } if delta == "world!"));
    let completed_idx = all_events
        .iter()
        .position(|e| matches!(e, AgentEvent::Completed { .. }));

    assert!(
        run_started_idx < delta1_idx,
        "RunStarted should precede first AssistantTextDelta"
    );
    assert!(
        delta1_idx < delta2_idx,
        "first AssistantTextDelta should precede second"
    );
    assert!(
        delta2_idx < completed_idx,
        "second AssistantTextDelta should precede Completed"
    );
}

