/// Verifies that the usage information in the SSE `message_delta` event is
/// propagated through to the `UsageUpdated` event emitted by the session.
#[tokio::test]
async fn session_usage_from_sse_fixtures() {
    let factory = Arc::new(FakeAnthropicHttpClient::new());
    let model_client = Arc::new(FakeModelClient::new(factory));
    let backend = Arc::new(GenericModelBackend::new(model_client));

