// ===========================================================================
// Model Layer Types (inline stand-ins for harness-model)
// ===========================================================================

/// Provider-neutral model capabilities — mirrors `harness_model::request::ModelCapabilities`.
#[derive(Debug, Clone, Default)]
struct ModelCapabilities {
    streaming: bool,
    reasoning: bool,
    tool_calls: bool,
    parallel_tool_calls: bool,
}

/// Provider-neutral model event — mirrors `harness_model::events::ModelEvent`.
#[derive(Debug, Clone)]
enum ModelEvent {
    TextDelta {
        delta: String,
    },
    ReasoningDelta {
        delta: String,
    },
    ToolCallStarted {
        id: ToolCallId,
        name: String,
        arguments: serde_json::Value,
    },
    UsageUpdate {
        usage: ModelUsage,
    },
    Completed {
        result: ModelResult,
    },
    Error {
        error: String,
    },
}

/// Provider-neutral model result — mirrors `harness_model::events::ModelResult`.
#[derive(Debug, Clone, Default)]
struct ModelResult {
    usage: ModelUsage,
    finish_reason: String,
}

/// Provider-neutral model error — mirrors `harness_model::events::ModelError`.
#[derive(Debug, Clone)]
struct ModelError {
    message: String,
}

/// Provider-neutral model request — mirrors `harness_model::request::ModelRequest`.
#[derive(Debug, Clone)]
struct ModelRequest {
    model: String,
    system_prompt: String,
    messages: Vec<harness_protocol::messages::AgentMessage>,
    tools: Vec<ToolDescriptor>,
    max_tokens: u64,
    temperature: Option<f64>,
}

/// Provider-neutral model client trait — mirrors `harness_model::client::ModelClient`.
#[async_trait]
trait ModelClient: Send + Sync {
    fn capabilities(&self) -> ModelCapabilities;
    async fn stream(
        &self,
        request: ModelRequest,
    ) -> Result<(Vec<ModelEvent>, ModelResult), ModelError>;
}

// ===========================================================================
// Inline SSE parser — simulates `crate::wire::parse_sse_events`
// ===========================================================================

/// A single parsed Anthropic SSE event.
#[derive(Debug, Clone)]
struct SseEvent {
    event_type: String,
    data: serde_json::Value,
}

/// Minimal SSE parser that splits raw SSE bytes into [`SseEvent`]s.
///
/// Matches the planned `crate::wire::parse_sse_events` signature.
fn parse_sse_events(raw: &[u8]) -> Vec<SseEvent> {
    let text = std::str::from_utf8(raw).expect("SSE fixtures are valid UTF-8");
    let mut events = Vec::new();
    let mut current_event = String::new();
    let mut current_data = String::new();

    for line in text.lines() {
        if line.starts_with("event: ") {
            current_event = line.trim_start_matches("event: ").to_string();
        } else if line.starts_with("data: ") {
            current_data.push_str(line.trim_start_matches("data: "));
        } else if line.is_empty() && !current_event.is_empty() {
            // End of an SSE event block
            if let Ok(data) = serde_json::from_str::<serde_json::Value>(&current_data) {
                events.push(SseEvent {
                    event_type: current_event.clone(),
                    data,
                });
            }
            current_event.clear();
            current_data.clear();
        }
    }

    events
}

// ===========================================================================
// SSE-to-ModelEvent translation — simulates `crate::wire::translate_to_model_events`
// ===========================================================================

/// Translate parsed Anthropic SSE events into a `Vec<ModelEvent>` and a
/// final `ModelResult`.
///
/// This mirrors the planned `crate::wire::sse_to_model_events` function.
fn sse_to_model_events(events: Vec<SseEvent>) -> (Vec<ModelEvent>, ModelResult) {
    let mut model_events = Vec::new();
    let mut final_usage = ModelUsage::default();
    let mut finish_reason = String::from("end_turn");

    for event in &events {
        match event.event_type.as_str() {
            "content_block_delta" => {
                let delta = &event.data["delta"];
                match delta["type"].as_str() {
                    Some("text_delta") => {
                        let text = delta["text"].as_str().unwrap_or_default();
                        if !text.is_empty() {
                            model_events.push(ModelEvent::TextDelta {
                                delta: text.to_string(),
                            });
                        }
                    }
                    Some("thinking_delta") => {
                        let thinking = delta["thinking"].as_str().unwrap_or_default();
                        if !thinking.is_empty() {
                            model_events.push(ModelEvent::ReasoningDelta {
                                delta: thinking.to_string(),
                            });
                        }
                    }
                    _ => {}
                }
            }
            "content_block_start" => {
                let block = &event.data["content_block"];
                if block["type"].as_str() == Some("tool_use") {
                    let name = block["name"].as_str().unwrap_or("unknown").to_string();
                    let arguments = block["input"].clone();
                    if arguments.is_null() {
                        continue;
                    }
                    model_events.push(ModelEvent::ToolCallStarted {
                        id: ToolCallId::new(),
                        name,
                        arguments,
                    });
                }
            }
            "message_delta" => {
                if let Some(usage) = event.data.get("usage") {
                    final_usage = ModelUsage {
                        input_tokens: UsageValue::new(usage["input_tokens"].as_u64()),
                        output_tokens: UsageValue::new(usage["output_tokens"].as_u64()),
                        ..Default::default()
                    };
                }
                if let Some(delta) = event.data.get("delta") {
                    if let Some(reason) = delta["stop_reason"].as_str() {
                        finish_reason = reason.to_string();
                    }
                }
            }
            "message_stop" => {
                // End of stream — no additional data in this event.
            }
            _ => {}
        }
    }

    // Emit a usage update and completed event at the end.
    model_events.push(ModelEvent::UsageUpdate {
        usage: final_usage.clone(),
    });
    model_events.push(ModelEvent::Completed {
        result: ModelResult {
            usage: final_usage,
            finish_reason,
        },
    });

    (model_events, ModelResult::default())
}

// ===========================================================================
// FakeAnthropicHttpClient — returns pre-recorded SSE for matching patterns
// ===========================================================================

/// A fake HTTP client that returns pre-recorded SSE byte sequences.
///
/// The client inspects the request payload to decide which fixture to return:
/// - Requests containing `"calculator"` in messages → `TOOL_CALL_SSE`
/// - Requests containing `"read_file"` or `"search"` → `PARALLEL_TOOL_CALL_SSE`
/// - Requests containing `"think"` or `"reason"` → `THINKING_RESPONSE_SSE`
/// - All other requests → `TEXT_RESPONSE_SSE`
///
/// This pattern-matching simulates different model behaviours deterministically
/// without any network access.
struct FakeAnthropicHttpClient {
    /// The initial bytes of the HTTP response (status line + headers).
    response_prefix: Vec<u8>,
}

impl FakeAnthropicHttpClient {
    fn new() -> Self {
        // Standard HTTP/1.1 200 response with SSE content-type.
        let prefix = b"HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nCache-Control: no-cache\r\nConnection: keep-alive\r\n\r\n";
        Self {
            response_prefix: prefix.to_vec(),
        }
    }

    /// Select a fixture SSE body based on the request content.
    fn select_fixture(request_body: &str) -> &'static str {
        if request_body.contains("calculator") || request_body.contains("compute") {
            TOOL_CALL_SSE
        } else if request_body.contains("read_file") || request_body.contains("search") {
            PARALLEL_TOOL_CALL_SSE
        } else if request_body.contains("think") || request_body.contains("reason") {
            THINKING_RESPONSE_SSE
        } else {
            TEXT_RESPONSE_SSE
        }
    }

    /// Return the full HTTP response bytes for a given request body.
    ///
    /// This is the method the fake HTTP transport calls instead of opening
    /// a real TCP/TLS connection.
    fn respond_to(&self, request_body: &str) -> Vec<u8> {
        let body = Self::select_fixture(request_body);
        let mut response = self.response_prefix.clone();
        response.extend_from_slice(body.as_bytes());
        response
    }
}

// ===========================================================================
// FakeModelClient — implements ModelClient using FakeAnthropicHttpClient
// ===========================================================================

struct FakeModelClient {
    http_client: Arc<FakeAnthropicHttpClient>,
}

impl FakeModelClient {
    fn new(http_client: Arc<FakeAnthropicHttpClient>) -> Self {
        Self { http_client }
    }
}

#[async_trait]
impl ModelClient for FakeModelClient {
    fn capabilities(&self) -> ModelCapabilities {
        ModelCapabilities {
            streaming: true,
            reasoning: true,
            tool_calls: true,
            parallel_tool_calls: true,
        }
    }

    async fn stream(
        &self,
        request: ModelRequest,
    ) -> Result<(Vec<ModelEvent>, ModelResult), ModelError> {
        // --- Step 1: Serialize the request to JSON (simulating Anthropic wire format) ---
        let request_body = serde_json::to_string(&serde_json::json!({
            "model": request.model,
            "system": request.system_prompt,
            "messages": request.messages.iter().map(|m| serde_json::json!({
                "role": format!("{:?}", m.role).to_lowercase(),
                "content": m.content.iter().map(|c| match c {
                    harness_protocol::messages::ContentBlock::Text { text } => {
                        serde_json::json!({"type": "text", "text": text})
                    }
                    _ => serde_json::json!({"type": "text", "text": ""})
                }).collect::<Vec<_>>(),
            })).collect::<Vec<_>>(),
            "max_tokens": request.max_tokens,
            "temperature": request.temperature,
        }))
        .unwrap_or_default();

        // --- Step 2: Get the pre-recorded SSE response ---
        let response_bytes = self.http_client.respond_to(&request_body);

        // --- Step 3: Parse SSE events (simulating wire.rs) ---
        let sse_events = parse_sse_events(&response_bytes);

        // --- Step 4: Translate SSE events to ModelEvents (simulating wire.rs) ---
        let (model_events, result) = sse_to_model_events(sse_events);

        Ok((model_events, result))
    }
}

// ===========================================================================
// GenericModelBackend — wraps a ModelClient into an ExecutionBackend
//
// This mirrors the planned `harness_generic_backend::GenericModelBackend`.
// ===========================================================================

struct GenericModelBackend {
    descriptor: BackendDescriptor,
    model_client: Arc<dyn ModelClient>,
}

impl GenericModelBackend {
    fn new(model_client: Arc<dyn ModelClient>) -> Self {
        let caps = model_client.capabilities();
        Self {
            descriptor: BackendDescriptor {
                id: harness_protocol::ids::BackendId::new(),
                name: "generic-model-backend".to_string(),
                description: "Generic model backend with inline SSE fixtures".to_string(),
                capabilities: BackendCapabilities {
                    streaming: caps.streaming,
                    reasoning_stream: caps.reasoning,
                    tool_calls: caps.tool_calls,
                    parallel_tool_calls: caps.parallel_tool_calls,
                    host_managed_tools: true,
                    ..Default::default()
                },
            },
            model_client,
        }
    }

    /// Build a `ModelRequest` from an `ExecutionRequest`.
    fn build_model_request(request: &ExecutionRequest) -> ModelRequest {
        ModelRequest {
            model: "claude-sonnet-4-20250513".to_string(),
            system_prompt: request.system_prompt.clone(),
            messages: request.messages.clone(),
            tools: request.tools.clone(),
            max_tokens: 8192,
            temperature: None,
        }
    }

    /// Translate a `ModelEvent` into zero or more `ExecutionEvent`s.
    fn translate_event(request_id: RequestId, event: &ModelEvent) -> Vec<ExecutionEvent> {
        match event {
            ModelEvent::TextDelta { delta } => {
                vec![ExecutionEvent::TextDelta {
                    request_id,
                    delta: delta.clone(),
                }]
            }
            ModelEvent::ReasoningDelta { delta } => {
                vec![ExecutionEvent::ReasoningDelta {
                    request_id,
                    delta: delta.clone(),
                }]
            }
            ModelEvent::ToolCallStarted { id, name, arguments } => {
                vec![ExecutionEvent::ToolCallRequested {
                    request_id,
                    call: ToolCall {
                        id: *id,
                        name: name.clone(),
                        arguments: arguments.clone(),
                    },
                }]
            }
            ModelEvent::UsageUpdate { usage } => {
                vec![ExecutionEvent::UsageUpdate {
                    request_id,
                    usage: usage.clone(),
                }]
            }
            ModelEvent::Completed { result } => {
                vec![ExecutionEvent::Completed {
                    request_id,
                    result: ExecutionResult {
                        request_id,
                        usage: result.usage.clone(),
                        cost: Cost::default(),
                        finish_reason: result.finish_reason.clone(),
                    },
                }]
            }
            ModelEvent::Error { error } => {
                vec![ExecutionEvent::Error {
                    request_id,
                    error: ExecutionError::BackendError {
                        message: error.clone(),
                        code: "MODEL_ERROR".to_string(),
                    },
                }]
            }
        }
    }
}

#[async_trait]
impl ExecutionBackend for GenericModelBackend {
    fn descriptor(&self) -> BackendDescriptor {
        self.descriptor.clone()
    }

    fn capabilities(&self) -> BackendCapabilities {
        self.descriptor.capabilities.clone()
    }

    async fn execute(
        &self,
        request: ExecutionRequest,
        sink: broadcast::Sender<ExecutionEvent>,
        _cancel: CancellationToken,
    ) -> Result<ExecutionResult, ExecutionError> {
        let request_id = request.request_id;

        // 1. Convert ExecutionRequest → ModelRequest
        let model_request = Self::build_model_request(&request);

        // 2. Call the model client
        let (model_events, model_result) = self
            .model_client
            .stream(model_request)
            .await
            .map_err(|e| ExecutionError::BackendError {
                message: e.message,
                code: "MODEL_ERROR".to_string(),
            })?;

        // 3. Translate & stream ModelEvents → ExecutionEvents
        for model_event in &model_events {
            let exec_events = Self::translate_event(request_id, model_event);
            for exec_event in exec_events {
                let _ = sink.send(exec_event);
            }
        }

        // 4. Return the final result
        Ok(ExecutionResult {
            request_id,
            usage: model_result.usage,
            cost: Cost::default(),
            finish_reason: model_result.finish_reason,
        })
    }
}

