/// Sends a prompt that triggers a tool-use SSE fixture and verifies the
/// event stream contains a `ToolCallRequested` event with the expected
/// tool name (`"calculator"`) and arguments (`{"expression": "2 + 2"}`).
#[tokio::test]
async fn session_tool_call_from_sse_fixtures() {
    let factory = Arc::new(FakeAnthropicHttpClient::new());
    let model_client = Arc::new(FakeModelClient::new(factory));
    let backend = Arc::new(GenericModelBackend::new(model_client));

    let tool_registry = Arc::new(NoTools);

    let handle = Harness::new()
        .session()
        .backend(backend)
        .tools(tool_registry)
        .start()
        .await
        .expect("SessionBuilder::start() should succeed");

    let mut rx = handle.subscribe();

    handle
        .send("use the calculator to compute 2 + 2")
        .await
        .expect("SessionHandle::send() should succeed");

    // Collect events until Completed is observed.
    let mut all_events: Vec<AgentEvent> = Vec::new();
    for _ in 0..50 {
        let batch = drain_events(&mut rx);
        if !batch.is_empty() {
            all_events.extend(batch);
            if all_events
                .iter()
                .any(|e| matches!(e, AgentEvent::Completed { .. }))
            {
                break;
            }
        }
        tokio::time::sleep(std::time::Duration::from_millis(20)).await;
    }

    // Verify a ToolCallRequested event was emitted with the correct tool.
    let tool_call_events: Vec<&AgentEvent> = all_events
        .iter()
        .filter(|e| matches!(e, AgentEvent::ToolCallRequested { .. }))
        .collect();

    assert_eq!(
        tool_call_events.len(),
        1,
        "expected exactly one ToolCallRequested event; got: {:?}",
        tool_call_events
    );

    match &tool_call_events[0] {
        AgentEvent::ToolCallRequested { call } => {
            assert_eq!(call.name, "calculator", "tool name should be 'calculator'");
            assert_eq!(
                call.arguments,
                serde_json::json!({"expression": "2 + 2"}),
                "tool arguments should match fixture"
            );
        }
        other => panic!("expected ToolCallRequested, got {:?}", other),
    }

    // Verify ordering: RunStarted < ToolCallRequested < Completed.
    let run_idx = all_events
        .iter()
        .position(|e| matches!(e, AgentEvent::RunStarted { .. }));
    let tool_idx = all_events
        .iter()
        .position(|e| matches!(e, AgentEvent::ToolCallRequested { .. }));
    let completed_idx = all_events
        .iter()
        .position(|e| matches!(e, AgentEvent::Completed { .. }));

    assert!(
        run_idx < tool_idx,
        "RunStarted should precede ToolCallRequested"
    );
    assert!(
        tool_idx < completed_idx,
        "ToolCallRequested should precede Completed"
    );
}

