        .collect();

    assert!(
        !usage_events.is_empty(),
        "expected at least one UsageUpdated event"
    );

    // The TEXT_RESPONSE_SSE fixture specifies input_tokens=10, output_tokens=5.
    // The agent aggregates usage after the execution result arrives.
    for usage_event in &usage_events {
        match usage_event {
            AgentEvent::UsageUpdated { usage } => {
                let input = usage.total_usage.input_tokens.value();
                let output = usage.total_usage.output_tokens.value();
                // Verify the fixture token counts are propagated.
                if let Some(in_tokens) = input {
                    assert_eq!(
                        in_tokens, 10,
