// ===========================================================================
// Test: deterministic zero-network behaviour
// ===========================================================================

/// Verifies that running the same prompt twice against the same fixtures
/// produces identical event sequences (token-perfect determinism).
#[tokio::test]
async fn session_deterministic_zero_network() {
    async fn run_session(prompt: &str) -> Vec<AgentEvent> {
        let factory = Arc::new(FakeAnthropicHttpClient::new());
        let model_client = Arc::new(FakeModelClient::new(factory));
        let backend = Arc::new(GenericModelBackend::new(model_client));
        let tool_registry = Arc::new(NoTools);

        let handle = Harness::new()
            .session()
            .backend(backend)
            .tools(tool_registry)
            .start()
            .await
            .expect("SessionBuilder::start() should succeed");

        let mut rx = handle.subscribe();

        handle
            .send(prompt)
            .await
            .expect("SessionHandle::send() should succeed");

        let mut events: Vec<AgentEvent> = Vec::new();
        for _ in 0..50 {
            let batch = drain_events(&mut rx);
            if !batch.is_empty() {
                events.extend(batch);
                if events
                    .iter()
                    .any(|e| matches!(e, AgentEvent::Completed { .. }))
                {
                    break;
                }
            }
            tokio::time::sleep(std::time::Duration::from_millis(20)).await;
        }
        events
    }

    let prompt = "write a greeting";
    let events_a = run_session(prompt).await;
    let events_b = run_session(prompt).await;

    // Filter out events that contain IDs (RunStarted, ToolCallRequested,
    // AssistantMessageStarted, etc.) since IDs are non-deterministic.
    // Only compare the text-content events and structural markers.
    let comparable_a: Vec<&AgentEvent> = events_a
        .iter()
        .filter(|e| {
            matches!(
                e,
                AgentEvent::AssistantTextDelta { .. } | AgentEvent::Completed { .. }
            )
        })
        .collect();
    let comparable_b: Vec<&AgentEvent> = events_b
        .iter()
        .filter(|e| {
            matches!(
                e,
                AgentEvent::AssistantTextDelta { .. } | AgentEvent::Completed { .. }
            )
        })
        .collect();

    assert_eq!(
        comparable_a.len(),
        comparable_b.len(),
        "determinism violation: different number of comparable events"
    );

    for (i, (a, b)) in comparable_a.iter().zip(comparable_b.iter()).enumerate() {
        match (a, b) {
            (
                AgentEvent::AssistantTextDelta { delta: da, .. },
                AgentEvent::AssistantTextDelta { delta: db, .. },
            ) => {
                assert_eq!(
                    da, db,
                    "determinism violation at text delta index {}: '{}' vs '{}'",
                    i, da, db
                );
            }
            (
                AgentEvent::Completed { outcome: oa },
                AgentEvent::Completed { outcome: ob },
            ) => {
                assert_eq!(
                    oa, ob,
                    "determinism violation at completed: {:?} vs {:?}",
                    oa, ob
                );
            }
            _ => panic!(
                "determinism violation at index {}: mismatched event types {:?} vs {:?}",
                i, a, b
            ),
        }
    }

    // Verify that no network calls were made by checking no errors occurred.
    assert!(
        !events_a
            .iter()
            .any(|e| matches!(e, AgentEvent::Failed { .. })),
        "first run should have no failures (zero network)"
    );
    assert!(
        !events_b
            .iter()
            .any(|e| matches!(e, AgentEvent::Failed { .. })),
        "second run should have no failures (zero network)"
    );
}

//! Anthropic Messages API client implementing [`ModelClient`].
//!
//! [`ModelClient`]: harness_model::client::ModelClient

use async_trait::async_trait;
use tracing::instrument;

use harness_model::client::ModelClient;
use harness_model::events::{ModelError, ModelEvent, ModelResult};
use harness_model::request::{ModelCapabilities, ModelRequest};

use crate::config::AnthropicConfig;
use crate::wire::{
    build_system, convert_messages, tool_descriptor_to_anthropic, AnthropicRequest,
    AnthropicSseParser, AnthropicThinking,
};

/// Client for the Anthropic Messages API.
///
/// Implements [`ModelClient`] by converting [`ModelRequest`] to the Anthropic
/// wire format, sending HTTP POST requests to the Anthropic API, and parsing
/// the Server-Sent Events (SSE) response stream into [`ModelEvent`]s.
///
/// The client is constructed with an [`AnthropicConfig`] that controls the
/// API key, base URL, default model, timeout, and other settings.
///
/// # Capabilities
///
/// The client advertises support for streaming, reasoning / extended thinking,
/// tool calls, and parallel tool calls.
pub struct AnthropicClient {
    /// Configuration for the Anthropic API.
    config: AnthropicConfig,
    /// Reusable HTTP client built with the configured request timeout.
    http_client: reqwest::Client,
}

impl AnthropicClient {
    /// Create a new [`AnthropicClient`] from the given configuration.
    ///
    /// The underlying `reqwest::Client` is built with the request timeout
    /// specified in `config.request_timeout`. Construction panics only if
    /// `reqwest::Client::builder()` fails, which should never happen with
    /// the default builder settings used here.
    pub fn new(config: AnthropicConfig) -> Self {
        let http_client = reqwest::Client::builder()
            .timeout(config.request_timeout)
            .build()
            .expect("reqwest::ClientBuilder::build should not fail with default settings");
        Self { config, http_client }
    }
}

#[async_trait]
impl ModelClient for AnthropicClient {
    /// Returns the capabilities supported by this Anthropic client.
    ///
    /// All capabilities — streaming, reasoning (extended thinking),
    /// tool calls, and parallel tool calls — are supported.
    fn capabilities(&self) -> ModelCapabilities {
        ModelCapabilities {
            streaming: true,
            reasoning: true,
            tool_calls: true,
            parallel_tool_calls: true,
        }
    }

    /// Execute a streaming request against the Anthropic Messages API.
    ///
    /// This method:
    /// 1. Converts the [`ModelRequest`] into an [`AnthropicRequest`] using
    ///    the conversion functions from [`wire`](crate::wire).
    /// 2. Sends an HTTP POST to `{config.base_url}/v1/messages` with the
    ///    required Anthropic headers (`x-api-key`, `anthropic-version`,
    ///    `content-type`).
    /// 3. On success (HTTP 2xx), parses the SSE response body using
    ///    [`AnthropicSseParser`] and forwards each parsed [`ModelEvent`]
    ///    through the `events` broadcast channel.
    /// 4. On HTTP 429, reads the `retry-after-ms` header and returns
    ///    [`ModelError::RateLimited`].
    /// 5. On other HTTP errors, returns [`ModelError::BackendError`] with
    ///    the status code and response body.
    ///
    /// # Cancellation
    ///
    /// The `cancel` token is checked before forwarding each event. When
    /// cancellation is signalled the method returns [`ModelError::Cancelled`]
    /// immediately.
    #[instrument(skip(self, request, events, cancel))]
    async fn stream(
        &self,
        request: ModelRequest,
        events: tokio::sync::broadcast::Sender<ModelEvent>,
        cancel: tokio_util::sync::CancellationToken,
    ) -> Result<ModelResult, ModelError> {
        // ------------------------------------------------------------------
        // Step 1: Convert ModelRequest to AnthropicRequest
        // ------------------------------------------------------------------
        let max_tokens = request
            .max_tokens
            .unwrap_or(self.config.default_max_tokens);

        let anthropic_request = AnthropicRequest {
            model: request
                .model
                .unwrap_or_else(|| self.config.default_model.clone()),
            system: if !request.system_prompt.is_empty() {
                Some(request.system_prompt)
            } else {
                build_system(&request.messages)
            },
            messages: convert_messages(&request.messages),
            tools: if request.tools.is_empty() {
                None
            } else {
                Some(
                    request
                        .tools
                        .iter()
                        .map(tool_descriptor_to_anthropic)
                        .collect(),
                )
            },
            max_tokens,
            temperature: request.temperature,
            stop_sequences: if request.stop_sequences.is_empty() {
                None
            } else {
                Some(request.stop_sequences)
            },
            thinking: if request.extended_thinking {
                // Anthropic requires budget_tokens < max_tokens with at least
                // 1024 tokens left for the response.  We reserve 1024 tokens
                // for the output and clamp to at least 1024 for thinking.
                let budget = max_tokens.saturating_sub(1024).max(1024);
                Some(AnthropicThinking {
                    kind: "enabled".to_string(),
                    budget_tokens: budget,
                })
            } else {
                None
            },
        };

        // ------------------------------------------------------------------
        // Step 2: Send HTTP POST request
        // ------------------------------------------------------------------
        let url = format!("{}/v1/messages", self.config.base_url);

        let response = self
            .http_client
            .post(&url)
            .header("x-api-key", &self.config.api_key)
            .header("anthropic-version", "2023-06-01")
            .header("content-type", "application/json")
            .json(&anthropic_request)
            .send()
            .await
            .map_err(|e| ModelError::BackendError {
                message: format!("HTTP request failed: {e}"),
                code: String::from("request_failed"),
            })?;

        // ------------------------------------------------------------------
        // Step 3: Handle response status
        // ------------------------------------------------------------------
        let status = response.status();

        if status.is_success() {
            Self::handle_success_response(response, &events, &cancel).await
        } else if status.as_u16() == 429 {
            Self::handle_rate_limit(response)
        } else {
            Self::handle_error_response(response, status).await
        }
    }
}

// ---------------------------------------------------------------------------
// Private helpers
// ---------------------------------------------------------------------------

impl AnthropicClient {
    /// Parse a successful (2xx) SSE response and forward events.
    async fn handle_success_response(
        response: reqwest::Response,
        events: &tokio::sync::broadcast::Sender<ModelEvent>,
        cancel: &tokio_util::sync::CancellationToken,
    ) -> Result<ModelResult, ModelError> {
        // Parse the SSE response body into events and final result.
        let parser = AnthropicSseParser::from_response(response).await?;
        let events_list = parser.into_events();

        let mut final_result: Option<ModelResult> = None;

        for event in events_list {
            // Honour cancellation.
            if cancel.is_cancelled() {
                return Err(ModelError::Cancelled);
            }

            // Capture the ModelResult from the Completed event so we
            // can return it after forwarding all events.
            if let ModelEvent::Completed { result } = &event {
                final_result = Some(result.clone());
            }

            // Forward the event to the caller via the broadcast channel.
            // If the receiver has been dropped the send will fail — we
            // ignore that because there is nothing meaningful we can do.
            let _ = events.send(event);
        }

        // The SSE stream must end with a Completed event.  If it does not,
        // something went wrong with the protocol.
        final_result.ok_or_else(|| ModelError::Protocol {
            message: String::from("SSE stream ended without a completed result"),
        })
    }

    /// Handle an HTTP 429 rate-limit response.
    fn handle_rate_limit(
        response: reqwest::Response,
    ) -> Result<ModelResult, ModelError> {
        let retry_after = response
            .headers()
            .get("retry-after-ms")
            .and_then(|v| v.to_str().ok())
            .and_then(|v| v.parse::<u64>().ok());

        Err(ModelError::RateLimited { retry_after })
    }

    /// Handle a non-success, non-429 HTTP response.
    async fn handle_error_response(
        response: reqwest::Response,
        status: reqwest::StatusCode,
    ) -> Result<ModelResult, ModelError> {
        let body = response.text().await.unwrap_or_default();
        Err(ModelError::BackendError {
            message: format!("HTTP {status}: {body}"),
            code: status.as_u16().to_string(),
        })
    }
}

//! Anthropic usage mapping and cost calculation.
//!
//! This module provides [`AnthropicUsageMapper`] for converting raw usage data
//! from the Anthropic Messages API into harness-protocol [`ModelUsage`] and
//! computing [`Cost`] from a per-model rate table.
//!
//! # Mapping
//!
//! | Anthropic field                     | `ModelUsage` field        |
//! |-------------------------------------|---------------------------|
//! | `input_tokens`                      | `input_tokens`            |
//! | `output_tokens`                     | `output_tokens`           |
//! | `cache_read_input_tokens`           | `cache_read_tokens`       |
//! | `cache_write_input_tokens`          | `cache_write_tokens`      |
//! | *(not exposed by Anthropic)*        | `reasoning_tokens: None`  |
//! | `input_tokens + output_tokens`      | `total_tokens`            |
//!
//! # Cost calculation
//!
//! Costs are computed via [`calculate_cost`] using a built-in rate table keyed
//! by model name. Cache read tokens are billed at the input rate; cache write
//! tokens are billed at 1.25× the input rate. The returned [`Cost`] always has
//! `source = CostSource::Calculated`.

use rust_decimal::Decimal;

use harness_protocol::usage::{Cost, CostSource, ModelUsage, UsageValue};

// ---------------------------------------------------------------------------
// RawAnthropicUsage
// ---------------------------------------------------------------------------

/// Raw usage data reported by the Anthropic Messages API.
///
/// This struct mirrors the `usage` object in an Anthropic API response
/// (`message_start` or `message_delta` payloads).
#[derive(Debug, Clone, Default)]
pub struct RawAnthropicUsage {
    /// Number of input tokens consumed.
    pub input_tokens: Option<u64>,
    /// Number of output tokens generated.
    pub output_tokens: Option<u64>,
    /// Tokens read from the prompt cache.
    pub cache_read_input_tokens: Option<u64>,
    /// Tokens written to the prompt cache.
    pub cache_write_input_tokens: Option<u64>,
}

// ---------------------------------------------------------------------------
// AnthropicUsageMapper
// ---------------------------------------------------------------------------

/// Maps raw Anthropic usage data into harness-protocol [`ModelUsage`] and
/// computes [`Cost`] from a per-model rate table.
///
/// # Rate table
///
/// The following models are currently recognised (rates are USD per million
/// tokens):
///
/// | Model                              | Input $/M | Output $/M |
/// |------------------------------------|-----------|------------|
/// | `claude-sonnet-4-20250513`         | $3.00     | $15.00     |
/// | `claude-3-5-haiku-20241022`        | $0.80     | $4.00      |
///
/// Unknown models yield zero rates, so the computed cost will be `$0.00`.
pub struct AnthropicUsageMapper;

impl AnthropicUsageMapper {
    /// Map raw Anthropic usage fields into a [`ModelUsage`].
    ///
    /// This performs the field mapping documented on the module and computes
    /// `total_tokens = input_tokens + output_tokens` when both are known.
    /// `reasoning_tokens` is always set to `None` (Anthropic does not expose
    /// this field).
    pub fn map_usage(raw: &RawAnthropicUsage, _model: &str) -> ModelUsage {
        let input = raw.input_tokens;
        let output = raw.output_tokens;
        let total = match (input, output) {
            (Some(i), Some(o)) => Some(i + o),
            _ => None,
        };

        ModelUsage {
            input_tokens: UsageValue::new(input),
            output_tokens: UsageValue::new(output),
            cache_read_tokens: UsageValue::new(raw.cache_read_input_tokens),
            cache_write_tokens: UsageValue::new(raw.cache_write_input_tokens),
            reasoning_tokens: UsageValue::new(None),
            total_tokens: UsageValue::new(total),
        }
    }

    /// Compute the cost of a usage record for the given model.
    ///
    /// Pricing is looked up from the built-in rate table (see [`Self`] for
    /// recognised models). The returned [`Cost`] has:
    ///
    /// * `amount_usd` — the computed total (input + output + cache) in USD, or
    ///   `None` if no token counts are available.
    /// * `source` — `Some(CostSource::Calculated)`.
    ///
    /// Cache read tokens are billed at the input rate. Cache write tokens are
    /// billed at 1.25× the input rate (Anthropic's pricing).
    pub fn calculate_cost(usage: &ModelUsage, model: &str) -> Cost {
        let rate = lookup_rate(model);

        let input_cost = usage
            .input_tokens
            .value()
            .map(|t| Decimal::from(t) * rate.input_rate / PER_MILLION);

        let output_cost = usage
            .output_tokens
            .value()
            .map(|t| Decimal::from(t) * rate.output_rate / PER_MILLION);

        let cache_read_cost = usage
            .cache_read_tokens
            .value()
            .map(|t| Decimal::from(t) * rate.input_rate / PER_MILLION);

        let cache_write_cost = usage.cache_write_tokens.value().map(|t| {
            Decimal::from(t) * rate.input_rate * CACHE_WRITE_MULTIPLIER / PER_MILLION
        });

        let total = [input_cost, output_cost, cache_read_cost, cache_write_cost]
            .iter()
            .fold(None, |acc: Option<Decimal>, cost| match (acc, cost) {
                (Some(a), Some(c)) => Some(a + c),
                (None, Some(c)) => Some(*c),
                (a, None) => a,
            });

        Cost {
            amount_usd: total,
            source: Some(CostSource::Calculated),
        }
    }
}

// ---------------------------------------------------------------------------
// Rate table constants
// ---------------------------------------------------------------------------

/// One million — used to convert per-million-token rates to per-token costs.
const PER_MILLION: Decimal = Decimal::from_parts(1_000_000, 0, 0, false, 0);

/// Multiplier for cache write tokens (1.25× the input rate).
const CACHE_WRITE_MULTIPLIER: Decimal = Decimal::from_parts(125, 0, 0, false, 2); // 1.25

/// A zero-valued [`Decimal`] constant, used as a fallback for unknown models.
const ZERO: Decimal = Decimal::from_parts(0, 0, 0, false, 0);

/// Pricing information for a model.
struct ModelRate {
    /// Cost per million input tokens (USD).
    input_rate: Decimal,
    /// Cost per million output tokens (USD).
    output_rate: Decimal,
}

/// Look up pricing rates for a given model name.
///
/// Uses prefix matching so that `"claude-sonnet-4-20250513"` matches exactly,
/// and future point-releases starting with the same prefix would also match.
///
/// Returns zero rates for unknown models.
fn lookup_rate(model: &str) -> ModelRate {
    match model {
        m if m.starts_with("claude-sonnet-4-20250513") => ModelRate {
            input_rate: Decimal::from_parts(300, 0, 0, false, 2),   // 3.00
            output_rate: Decimal::from_parts(1500, 0, 0, false, 2), // 15.00
        },
        m if m.starts_with("claude-3-5-haiku-20241022") => ModelRate {
            input_rate: Decimal::from_parts(80, 0, 0, false, 2),  // 0.80
            output_rate: Decimal::from_parts(400, 0, 0, false, 2), // 4.00
        },
        _ => ModelRate {
            input_rate: ZERO,
            output_rate: ZERO,
        },
    }
}

