//! Wire types for the Anthropic Messages API.
//!
//! This module provides:
//!
//! 1. **Request serialization types** — [`AnthropicRequest`], [`AnthropicMessage`],
//!    [`AnthropicContentBlock`], [`AnthropicTool`], [`AnthropicThinking`] — all
//!    deriving [`Serialize`] for direct use with `reqwest::Client::post().json()`.
//!
//! 2. **Conversion functions** — [`agent_message_to_anthropic`],
//!    [`tool_descriptor_to_anthropic`], [`build_system`], [`convert_messages`] —
//!    mapping harness-protocol types to their Anthropic wire equivalents.
//!
//! 3. **SSE response parser** — [`AnthropicSseParser`] that reads a
//!    [`reqwest::Response`] body, splits on `\n\n` boundaries, parses `event:` /
//!    `data:` lines, and produces [`ModelEvent`] values with full tool-call
//!    argument accumulation.

use std::collections::HashMap;

use serde::{Deserialize, Serialize};

use harness_model::events::{ModelError, ModelEvent, ModelResult};
use harness_protocol::ids::ToolCallId;
use harness_protocol::messages::{AgentMessage, ContentBlock, MessageRole};
use harness_protocol::tools::ToolDescriptor;
use harness_protocol::usage::{ModelUsage, UsageValue};

// ===========================================================================
// Request serialization types
// ===========================================================================

/// A complete request body for the Anthropic Messages API
/// (`POST /v1/messages`).
#[derive(Debug, Clone, Serialize)]
pub struct AnthropicRequest {
    /// The model identifier (e.g. `"claude-sonnet-4-20250513"`).
    pub model: String,
    /// System prompt — a string or array of text blocks.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub system: Option<String>,
    /// Conversation messages (user and assistant turns).
    pub messages: Vec<AnthropicMessage>,
    /// Tool definitions the model may call.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub tools: Option<Vec<AnthropicTool>>,
    /// Maximum tokens to generate in the response.
    pub max_tokens: u64,
    /// Sampling temperature.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub temperature: Option<f64>,
    /// Sequences that cause the model to stop generating.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub stop_sequences: Option<Vec<String>>,
    /// Extended thinking / reasoning configuration.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub thinking: Option<AnthropicThinking>,
}

/// A single message in the conversation.
#[derive(Debug, Clone, Serialize)]
pub struct AnthropicMessage {
    /// The participant role.
    pub role: AnthropicRole,
    /// Content blocks comprising the message body.
    pub content: Vec<AnthropicContentBlock>,
}

/// Participant role for an [`AnthropicMessage`].
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum AnthropicRole {
    /// The human user (also wraps tool results).
    User,
    /// The assistant / model.
    Assistant,
}

/// A content block inside a message.
///
/// The Anthropic API uses a tagged union via the `type` field.
#[derive(Debug, Clone, Serialize)]
#[serde(tag = "type")]
pub enum AnthropicContentBlock {
    /// Plain text content.
    #[serde(rename = "text")]
    Text {
        /// The text content.
        text: String,
    },
    /// A model-initiated tool call.
    #[serde(rename = "tool_use")]
    ToolUse {
        /// The tool call ID (Anthropic format, e.g. `"toolu_..."`).
        id: String,
        /// The tool name.
        name: String,
        /// The tool arguments.
        input: serde_json::Value,
    },
    /// A tool result submitted by the host.
    #[serde(rename = "tool_result")]
    ToolResult {
        /// The tool_use ID this result corresponds to.
        tool_use_id: String,
        /// The result content (text summary).
        content: String,
    },
}

/// A tool definition in the Anthropic format.
#[derive(Debug, Clone, Serialize)]
pub struct AnthropicTool {
    /// The name of the tool.
    pub name: String,
    /// A description of what the tool does.
    pub description: String,
    /// The JSON Schema for the tool's input.
    pub input_schema: serde_json::Value,
}

/// Configuration for extended thinking.
#[derive(Debug, Clone, Serialize)]
pub struct AnthropicThinking {
    /// Always `"enabled"`.
    #[serde(rename = "type")]
    pub kind: String,
    /// Maximum tokens to allocate for extended thinking.
    pub budget_tokens: u64,
}

// ===========================================================================
// Conversion functions — harness-protocol → Anthropic wire types
// ===========================================================================

/// Convert a single [`AgentMessage`] to an [`AnthropicMessage`].
///
/// # Panics
///
/// Panics if the message has role `System` — callers must filter system
/// messages via [`build_system`] / [`convert_messages`] first.
pub fn agent_message_to_anthropic(msg: &AgentMessage) -> AnthropicMessage {
    let role = match msg.role {
        MessageRole::User | MessageRole::Tool => AnthropicRole::User,
        MessageRole::Assistant => AnthropicRole::Assistant,
        MessageRole::System => {
            panic!("system messages must be filtered before agent_message_to_anthropic")
        }
    };

    let content: Vec<AnthropicContentBlock> = msg
        .content
        .iter()
        .filter_map(|block| match block {
            ContentBlock::Text { text } => {
                Some(AnthropicContentBlock::Text { text: text.clone() })
            }
            ContentBlock::ToolUse { call } => Some(AnthropicContentBlock::ToolUse {
                id: call.id.to_string(),
                name: call.name.clone(),
                input: call.arguments.clone(),
            }),
            ContentBlock::ToolResult { call_id, result } => {
                Some(AnthropicContentBlock::ToolResult {
                    tool_use_id: call_id.to_string(),
                    content: result.output_preview.clone(),
                })
            }
            ContentBlock::Image { .. } => {
                // Image content is not yet supported; skip.
                None
            }
        })
        .collect();

    AnthropicMessage { role, content }
}

/// Convert a [`ToolDescriptor`] to an [`AnthropicTool`].
pub fn tool_descriptor_to_anthropic(tool: &ToolDescriptor) -> AnthropicTool {
    AnthropicTool {
        name: tool.name.clone(),
        description: tool.description.clone(),
        input_schema: tool.input_schema.clone(),
    }
}

/// Build the `system` field value by concatenating all system messages.
///
/// Returns `None` if there are no system messages.
pub fn build_system(messages: &[AgentMessage]) -> Option<String> {
    let parts: Vec<&str> = messages
        .iter()
        .filter(|m| m.role == MessageRole::System)
        .filter_map(|m| {
            m.content
                .iter()
                .filter_map(|block| {
                    if let ContentBlock::Text { text } = block {
                        Some(text.as_str())
                    } else {
                        None
                    }
                })
                .next()
        })
        .collect();

    if parts.is_empty() {
        None
    } else {
        Some(parts.join("\n"))
    }
}

/// Convert all non-system [`AgentMessage`]s to [`AnthropicMessage`]s.
///
/// System messages are removed and should be placed in the `system` field
/// separately via [`build_system`].
pub fn convert_messages(messages: &[AgentMessage]) -> Vec<AnthropicMessage> {
    messages
        .iter()
        .filter(|m| m.role != MessageRole::System)
        .map(agent_message_to_anthropic)
        .collect()
}

