        assert_eq!(result.stop_reason, "end_turn");
        assert_eq!(result.usage.input_tokens.value(), Some(10));
        assert_eq!(result.usage.output_tokens.value(), Some(5));

        // Verify text delta was captured.
        let text_deltas: Vec<&str> = events
            .iter()
            .filter_map(|e| {
                if let ModelEvent::TextDelta { delta } = e {
                    if !delta.is_empty() {
                        Some(delta.as_str())
                    } else {
                        None
                    }
                } else {
                    None
                }
            })
            .collect();
        assert!(text_deltas.contains(&"Hello!"));
    }

    #[test]
    fn test_error_event() {
        let sse = concat!(
            "event: error\n",
            "data: {\"type\":\"error\",\"error\":{\"type\":\"invalid_request_error\",\
             \"message\":\"Bad request\"}}",
            "\n\n"
        );
        let (events, _) = parse_sse(sse);

        assert_eq!(events.len(), 1);
        match &events[0] {
            ModelEvent::Error { error } => match error {
                ModelError::BackendError { message, code } => {
                    assert_eq!(message, "Bad request");
                    assert_eq!(code, "invalid_request_error");
                }
                other => panic!("expected BackendError, got {other:?}"),
            },
            other => panic!("expected Error, got {other:?}"),
        }
    }

    #[test]
    fn test_empty_input_returns_empty_events() {
        let (events, result) = parse_sse("");
        assert!(events.is_empty());
        assert!(result.is_none());
    }

    #[test]
    fn test_multiple_sse_events_parsed_in_order() {
        // Simulate a realistic sequence: start, text, tool use, delta,
        // stop, message delta, message stop.
        let sse = concat!(
            "event: message_start\n",
            "data: {\"type\":\"message_start\",\"message\":{",
            "\"id\":\"msg_01\",\"type\":\"message\",\"role\":\"assistant\",",
            "\"content\":[],\"model\":\"claude-sonnet-4-20250513\",",
            "\"stop_reason\":null,\"stop_sequence\":null,",
            "\"usage\":{\"input_tokens\":5}}}",
            "\n\n",
            "event: content_block_start\n",
            "data: {\"type\":\"content_block_start\",\"index\":0,\
             \"content_block\":{\"type\":\"text\",\"text\":\"\"}}",
            "\n\n",
            "event: content_block_delta\n",
            "data: {\"type\":\"content_block_delta\",\"index\":0,\
             \"delta\":{\"type\":\"text\",\"text\":\"Sure!\"}}",
            "\n\n",
            "event: content_block_stop\n",
            "data: {\"type\":\"content_block_stop\",\"index\":0}",
            "\n\n",
            "event: content_block_start\n",
            "data: {\"type\":\"content_block_start\",\"index\":1,\
             \"content_block\":{\"type\":\"tool_use\",\"id\":\"toolu_xyz\",\"name\":\"get_weather\"}}",
            "\n\n",
            "event: content_block_delta\n",
            "data: {\"type\":\"content_block_delta\",\"index\":1,\
             \"delta\":{\"type\":\"input_json_delta\",\"partial_json\":\"{\\\"city\\\":\"}}",
            "\n\n",
            "event: content_block_delta\n",
            "data: {\"type\":\"content_block_delta\",\"index\":1,\
             \"delta\":{\"type\":\"input_json_delta\",\"partial_json\":\" \\\"Paris\\\"}\"}}",
            "\n\n",
            "event: content_block_stop\n",
            "data: {\"type\":\"content_block_stop\",\"index\":1}",
            "\n\n",
            "event: message_delta\n",
            "data: {\"type\":\"message_delta\",\"delta\":{\"stop_reason\":\"tool_use\",\
             \"stop_sequence\":null},\"usage\":{\"output_tokens\":15}}",
            "\n\n",
            "event: message_stop\n",
            "data: {\"type\":\"message_stop\"}",
            "\n\n"
        );
        let (events, result) = parse_sse(sse);

        assert!(result.is_some());
        let result = result.unwrap();
        assert_eq!(result.stop_reason, "tool_use");
        assert_eq!(result.usage.input_tokens.value(), Some(5));
        assert_eq!(result.usage.output_tokens.value(), Some(15));

        // Verify event ordering by type.
        let event_types: Vec<&str> = events
            .iter()
            .map(|e| match e {
                ModelEvent::TextDelta { .. } => "text_delta",
                ModelEvent::ToolCallStarted { .. } => "tool_started",
                ModelEvent::ToolCallDelta { .. } => "tool_delta",
                ModelEvent::ToolCallCompleted { .. } => "tool_completed",
                ModelEvent::UsageUpdate { .. } => "usage_update",
                ModelEvent::Completed { .. } => "completed",
                ModelEvent::Error { .. } => "error",
                ModelEvent::ReasoningDelta { .. } => "reasoning",
            })
            .collect::<Vec<_>>();

        // [usage, text_delta, text_delta, text_delta,
        //  tool_started, tool_delta, tool_delta, tool_completed,
        //  usage, completed]
        assert_eq!(
            event_types[0], "usage_update",
            "first event should be usage from message_start"
        );
        assert_eq!(
            event_types[4], "tool_started",
            "fifth event should be tool_started"
        );
        assert_eq!(
            event_types[7], "tool_completed",
            "eighth event should be tool_completed"
        );
        assert_eq!(
            event_types[9], "completed",
            "last event should be completed"
        );
    }

    #[test]
    fn test_tool_call_parse_failure_returns_protocol_error() {
        // Deliberately malformed partial JSON that can't be parsed.
        let sse = concat!(
            "event: content_block_start\n",
            "data: {\"type\":\"content_block_start\",\"index\":0,\
             \"content_block\":{\"type\":\"tool_use\",\"id\":\"toolu_bad\",\"name\":\"bad_tool\"}}",
            "\n\n",
            "event: content_block_delta\n",
            "data: {\"type\":\"content_block_delta\",\"index\":0,\
             \"delta\":{\"type\":\"input_json_delta\",\"partial_json\":\"{invalid json}\"}}",
            "\n\n",
            "event: content_block_stop\n",
            "data: {\"type\":\"content_block_stop\",\"index\":0}",
            "\n\n"
        );
        let result = AnthropicSseParser::parse_all(sse.as_bytes());
        assert!(result.is_err(), "should fail with Protocol error");
        if let Err(ModelError::Protocol { message }) = result {
            assert!(
                message.contains("bad_tool"),
                "error message should mention the tool name: {message}"
            );
        } else {
            panic!("expected Protocol error");
        }
    }

    #[test]
    fn test_unknown_event_type_is_ignored() {
        // This test verifies that unknown event types are silently handled.
        // Anthropic may add more event types in the future.
        let sse =
            concat!("event: unknown_event_type\n", "data: {\"type\":\"unknown\"}", "\n\n");
        let (events, _) = parse_sse(sse);
        // Unknown event produces empty TextDelta.
        assert!(events
            .iter()
            .all(|e| matches!(e, ModelEvent::TextDelta { delta } if delta.is_empty())));
    }
}

