//! Anthropic backend composition and integration factory.
//!
//! This module provides:
//!
//! 1. [`AnthropicBackend`] — a zero-sized constructor that composes
//!    [`AnthropicClient`] with [`GenericModelBackend`] so call sites can
//!    write `AnthropicBackend::new(config)` (matching spec §12's example).
//!
//! 2. [`AnthropicFactory`] — an [`IntegrationFactory`] implementation that
//!    deserializes an [`AnthropicConfig`] from JSON, constructs an
//!    [`AnthropicBackend`], and returns it as `Arc<dyn ExecutionBackend>`,
//!    enabling dynamic backend instantiation via the runtime's integration
//!    registry (spec §15/16).
//!
//! [`AnthropicClient`]: crate::client::AnthropicClient
//! [`GenericModelBackend`]: harness_generic_backend::GenericModelBackend

use std::sync::Arc;

use harness_generic_backend::GenericModelBackend;
use harness_protocol::backend::BackendDescriptor;
use harness_runtime::traits::ExecutionBackend;

use crate::client::AnthropicClient;
use crate::config::AnthropicConfig;

// ---------------------------------------------------------------------------
// AnthropicBackend
// ---------------------------------------------------------------------------

/// A zero-sized constructor that composes [`AnthropicClient`] (a
/// [`ModelClient`](harness_model::client::ModelClient) implementation) with
/// [`GenericModelBackend`] (an [`ExecutionBackend`] implementation).
///
/// # Usage
///
/// ```ignore
/// let backend: GenericModelBackend = AnthropicBackend::new(config);
/// let session = harness
///     .session()
///     .backend(Arc::new(backend))
///     // ...
///     .start()
///     .await?;
/// ```
pub struct AnthropicBackend;

impl AnthropicBackend {
    /// Create a new [`GenericModelBackend`] backed by the Anthropic API.
    ///
    /// This is a convenience constructor that:
    /// 1. Creates an [`AnthropicClient`] from the given [`AnthropicConfig`].
    /// 2. Wraps it in `Arc<dyn ModelClient>`.
    /// 3. Passes it to [`GenericModelBackend::new`].
    pub fn new(config: AnthropicConfig) -> GenericModelBackend {
        let client = Arc::new(AnthropicClient::new(config));
        GenericModelBackend::new(client)
    }
}

// ---------------------------------------------------------------------------
// IntegrationFactory
// ---------------------------------------------------------------------------

/// A factory that can create [`ExecutionBackend`] instances from a JSON
/// configuration blob.
///
/// This trait is used by the runtime's [`IntegrationRegistry`] to
/// reconstruct backends dynamically (spec §15/16). Each integration
/// family (Anthropic, OpenAI, Claude Code, …) implements this trait and
/// registers a singleton instance.
///
/// # Object safety
///
/// This trait is `dyn`-compatible — all methods take `&self` and return
/// owned values.
pub trait IntegrationFactory: Send + Sync {
    /// Returns the unique identifier for this integration family
    /// (e.g. `"anthropic"`, `"openai"`, `"claude-code"`).
    fn id(&self) -> &'static str;

    /// Returns a [`BackendDescriptor`] describing the integration's
    /// static capabilities and identity.
    fn descriptor(&self) -> BackendDescriptor;

    /// Create a new [`ExecutionBackend`] from a JSON configuration value.
    ///
    /// The `config_json` is deserialized into the integration-specific
    /// configuration type (e.g. [`AnthropicConfig`]). If deserialization
    /// fails, the error is returned as a boxed error.
    fn create(
        &self,
        config_json: serde_json::Value,
    ) -> Result<Arc<dyn ExecutionBackend>, Box<dyn std::error::Error>>;
}

// ---------------------------------------------------------------------------
// AnthropicFactory
// ---------------------------------------------------------------------------

/// A singleton [`IntegrationFactory`] for the Anthropic integration.
///
/// # Usage
///
/// ```ignore
/// let factory = Arc::new(AnthropicFactory);
/// registry.register(factory);
///
/// // Later, during session restore:
/// let config = serde_json::json!({
///     "api_key": "sk-ant-...",
///     "base_url": "https://api.anthropic.com",
///     "default_model": "claude-sonnet-4-20250513",
/// });
/// let backend = factory.create(config)?;
/// ```
pub struct AnthropicFactory;

impl IntegrationFactory for AnthropicFactory {
    fn id(&self) -> &'static str {
        "anthropic"
    }

    fn descriptor(&self) -> BackendDescriptor {
        BackendDescriptor {
            id: harness_protocol::ids::BackendId::new(),
            name: "Anthropic".to_string(),
            description: "Anthropic Messages API via GenericModelBackend".to_string(),
            capabilities: harness_protocol::backend::BackendCapabilities {
                streaming: true,
                reasoning_stream: true,
                tool_calls: true,
                parallel_tool_calls: true,
                host_managed_tools: true,
                ..Default::default()
            },
        }
    }

    fn create(
        &self,
        config_json: serde_json::Value,
    ) -> Result<Arc<dyn ExecutionBackend>, Box<dyn std::error::Error>> {
        let config: AnthropicConfig = serde_json::from_value(config_json)?;
        let backend = AnthropicBackend::new(config);
        Ok(Arc::new(backend))
    }
}

